        {{-- <script>
            document.addEventListener("DOMContentLoaded", function() {
                const calendarEl = document.getElementById("calendar");

                const schedules = @json($schedule);
                const today = @json(now()->toDateString());
                

                const availableDays = schedules.map(
                    schedule => Number(schedule.day_of_week)
                );

                // Generate calendar events
                const events = schedules.map(schedule => ({
                    title: `${schedule.start_time.substring(0, 5)} - ${schedule.end_time.substring(0, 5)} (2 slots)`,
                    daysOfWeek: [Number(schedule.day_of_week) % 7],
                    backgroundColor: "#ff7a00",
                    borderColor: "#ff7a00",
                    textColor: "#000000",
                    extendedProps: {
                        scheduleId: schedule.id
                    }
                }));

                // Open the booking modal
                
                function openBookingModal(date, daySchedules, selectedScheduleId = null) {
                    const modal = document.getElementById("bookingModal");
                    const bookingDate = document.getElementById("bookingDate");
                    const bookingSchedule = document.getElementById("bookingSchedule");
                    const bookingScheduleId = document.getElementById("bookingScheduleId");
                    const startTimeSelect = document.getElementById("bookingStartTime");
                    const endTimeSelect = document.getElementById("bookingEndTime");
                    const description = document.getElementById("bookingModalDescription");

                    if (!modal || !bookingDate || !bookingSchedule ||
                        !bookingScheduleId || !startTimeSelect || !endTimeSelect) {
                        console.error("Booking modal elements could not be found.");
                        return;
                    }


                    bookingDate.value = date;

                    bookingSchedule.innerHTML =
                        '<option value="">Choose a meeting time</option>';

                    startTimeSelect.innerHTML =
                        '<option value="">Choose start time</option>';

                    endTimeSelect.innerHTML =
                        '<option value="">Choose end time</option>';

                    daySchedules.forEach(schedule => {
                        const option = document.createElement("option");
                        option.value = schedule.id;
                        option.textContent =
                            `${schedule.start_time.substring(0, 5)} - ${schedule.end_time.substring(0, 5)}`;

                        bookingSchedule.appendChild(option);
                        console.log(schedule.duration_minutes);

                    });

                    if (selectedScheduleId !== null) {
                        bookingSchedule.value = String(selectedScheduleId);
                    }

                    function updateTimes() {
                        const schedule = daySchedules.find(
                            item => String(item.id) === bookingSchedule.value
                        );

                        startTimeSelect.innerHTML =
                            '<option value="">Choose start time</option>';

                        endTimeSelect.innerHTML =
                            '<option value="">Choose end time</option>';

                        bookingScheduleId.value = schedule ? schedule.id : "";

                        if (!schedule) return;

                        const start = schedule.start_time.substring(0, 5);
                        const end = schedule.end_time.substring(0, 5);

                        const startOption = new Option(start, start);
                        const endOption = new Option(end, end);

                        startTimeSelect.add(startOption);
                        endTimeSelect.add(endOption);

                        startTimeSelect.value = start;
                        endTimeSelect.value = end;
                    }

                    bookingSchedule.onchange = updateTimes;

                    updateTimes();

                    if (description) {
                        description.textContent =
                            `Choose your preferred meeting time for ${date}.`;
                    }

                    modal.style.display = "flex";
                }

                


                const calendar = new FullCalendar.Calendar(calendarEl, {
                    initialView: "dayGridMonth",

                    headerToolbar: {
                        left: "prev,next",
                        center: "title",
                        right: "dayGridMonth,timeGridWeek,timeGridDay"
                    },

                    buttonText: {
                        month: "Month",
                        week: "Week",
                        day: "Day"
                    },

                    validRange: {
                        start: today
                    },

                    events: events,

                    eventContent: function(arg) {
                        const lines = arg.event.title.split("\n");

                        return {
                            html: lines.map(line => `<div>${line}</div>`).join("")
                        };
                    },

                    dayCellDidMount: function(info) {
                        const day = ((info.date.getDay() + 6) % 7) + 1;
                        const dateString = [
                            info.date.getFullYear(),
                            String(info.date.getMonth() + 1).padStart(2, "0"),
                            String(info.date.getDate()).padStart(2, "0")
                        ].join("-");

                        if (!availableDays.includes(day) || dateString < today) {
                            info.el.style.backgroundColor = "#f3f4f6";
                            info.el.style.color = "#9ca3af";
                            info.el.style.cursor = "not-allowed";
                        } else {
                            info.el.style.cursor = "pointer";
                        }
                    },

                    // Click an available day
                    dateClick: function(info) {
                        const date = new Date(info.dateStr + "T12:00:00");
                        const day = ((date.getDay() + 6) % 7) + 1;

