        <script>
            document.addEventListener("DOMContentLoaded", function() {
                const calendarEl = document.getElementById("calendar");

                const schedules = @json($schedule);
                const today = @json(now()->toDateString());

                const availableDays = schedules.map(
                    schedule => Number(schedule.day_of_week)
                );

                // ===== Slot helpers (NEW) =====
                function toMinutes(time) {
                    const [h, m] = time.substring(0, 5).split(":").map(Number);
                    return h * 60 + m;
                }

                function toTime(minutes) {
                    const h = String(Math.floor(minutes / 60)).padStart(2, "0");
                    const m = String(minutes % 60).padStart(2, "0");
                    return `${h}:${m}`;
                }

                // Split a schedule into slots of duration_minutes
                function generateSlots(schedule) {
                    const duration = Number(schedule.duration_minutes) || 60;
                    const end = toMinutes(schedule.end_time);
                    let current = toMinutes(schedule.start_time);
                    const slots = [];

                    while (current + duration <= end) {
                        slots.push({
                            scheduleId: schedule.id,
                            start: toTime(current),
                            end: toTime(current + duration)
                        });
                        current += duration;
                    }

                    return slots;
                }

                // Generate calendar events (slot count is now calculated)
                const events = schedules.map(schedule => {
                    const count = generateSlots(schedule).length;

                    return {
                        title: `${schedule.start_time.substring(0, 5)} - ${schedule.end_time.substring(0, 5)} (${count} slot${count === 1 ? "" : "s"})`,
                        daysOfWeek: [Number(schedule.day_of_week) % 7],
                        backgroundColor: "#ff7a00",
                        borderColor: "#ff7a00",
                        textColor: "#000000",
                        extendedProps: {
                            scheduleId: schedule.id
                        }
                    };
                });

                // Open the booking modal
                function openBookingModal(date, daySchedules, selectedScheduleId = null) {
                    const modal = document.getElementById("bookingModal");
                    const bookingDate = document.getElementById("bookingDate");
                    const bookingScheduleId = document.getElementById("bookingScheduleId");
                    const slotSelect = document.getElementById("bookingSlot");
                    const startTimeInput = document.getElementById("bookingStartTime");
                    const endTimeInput = document.getElementById("bookingEndTime");
                    const description = document.getElementById("bookingModalDescription");

                    if (!modal || !bookingDate || !bookingScheduleId ||
                        !slotSelect || !startTimeInput || !endTimeInput) {
                        console.error("Booking modal elements could not be found.");
                        return;
                    }

                    bookingDate.value = date;
                    bookingScheduleId.value = "";
                    startTimeInput.value = "";
                    endTimeInput.value = "";
                    slotSelect.innerHTML = '<option value="">Choose a time slot</option>';

                    // Build all slots for the day
                    const allSlots = daySchedules.flatMap(schedule => generateSlots(schedule));

                    allSlots.forEach((slot, index) => {
                        const option = document.createElement("option");
                        option.value = index;
                        option.textContent = `${slot.start} - ${slot.end}`;
                        slotSelect.appendChild(option);
                    });

                    // If an event was clicked, preselect the first slot of that schedule
                    if (selectedScheduleId !== null) {
                        const firstIndex = allSlots.findIndex(
                            slot => String(slot.scheduleId) === String(selectedScheduleId)
                        );

                        if (firstIndex !== -1) {
                            slotSelect.value = String(firstIndex);
                        }
                    }

                    function applySlot() {
                        const slot = allSlots[slotSelect.value];

                        bookingScheduleId.value = slot ? slot.scheduleId : "";
                        startTimeInput.value = slot ? slot.start : "";
                        endTimeInput.value = slot ? slot.end : "";
                    }

                    slotSelect.onchange = applySlot;
                    applySlot();

                    if (description) {
                        description.textContent =
                            `Choose your preferred meeting time for ${date}.`;
                    }

                    modal.style.display = "flex";
                }

                const calendar = new FullCalendar.Calendar(calendarEl, {
                    initialView: "dayGridMonth",

                    headerToolbar: {
                        left: "prev,next",
                        center: "title",
                        right: "dayGridMonth,timeGridWeek,timeGridDay"
                    },

                    buttonText: {
                        month: "Month",
                        week: "Week",
                        day: "Day"
                    },

                    validRange: {
                        start: today
                    },

                    events: events,

                    eventContent: function(arg) {
                        const lines = arg.event.title.split("\n");

                        return {
                            html: lines.map(line => `<div>${line}</div>`).join("")
                        };
                    },

                    dayCellDidMount: function(info) {
                        const day = ((info.date.getDay() + 6) % 7) + 1;
                        const dateString = [
                            info.date.getFullYear(),
                            String(info.date.getMonth() + 1).padStart(2, "0"),
                            String(info.date.getDate()).padStart(2, "0")
                        ].join("-");

                        if (!availableDays.includes(day) || dateString < today) {
                            info.el.style.backgroundColor = "#f3f4f6";
                            info.el.style.color = "#9ca3af";
                            info.el.style.cursor = "not-allowed";
                        } else {
                            info.el.style.cursor = "pointer";
                        }
                    },

                    // Click an available day
                    dateClick: function(info) {
                        const date = new Date(info.dateStr + "T12:00:00");
                        const day = ((date.getDay() + 6) % 7) + 1;

                        if (info.dateStr < today || !availableDays.includes(day)) {
                            return;
                        }

                        const daySchedules = schedules.filter(
                            schedule => Number(schedule.day_of_week) === day
                        );

                        openBookingModal(info.dateStr, daySchedules);
                    },

                    // Click a schedule event
                    eventClick: function(info) {
                        const date = info.event.startStr.substring(0, 10);

                        if (date < today) {
                            return;
                        }

                        const scheduleId = info.event.extendedProps.scheduleId;

                        const schedule = schedules.find(
                            item => String(item.id) === String(scheduleId)
                        );

                        if (!schedule) {
                            return;
                        }

                        const daySchedules = schedules.filter(
                            item => Number(item.day_of_week) === Number(schedule.day_of_week)
                        );

                        openBookingModal(date, daySchedules, scheduleId);
                    }
                });

                calendar.render();

                // Close button
                const closeButton = document.getElementById("closeBookingModal");
                const modal = document.getElementById("bookingModal");

                if (closeButton && modal) {
                    closeButton.addEventListener("click", function() {
                        modal.style.display = "none";
                    });

                    // Close when clicking the dark overlay
                    modal.addEventListener("click", function(event) {
                        if (event.target === modal) {
                            modal.style.display = "none";
                        }
                    });

                    // Close when pressing Escape
                    document.addEventListener("keydown", function(event) {
                        if (event.key === "Escape") {
                            modal.style.display = "none";
                        }
                    });
                }
            });
        </script>




    </x-slot>


